public class Furniture{ 

  private String name; 

  public Furniture(){  
    name = "blob";  
  } 

  public Furniture(String n){   
    name = n;  
  } 

  public String toString(){  
    return name;  
  } 
} 

public class Table extends Furniture{ 
  private int legs; 

  public Table(int n){ 
    super("Ikea"); 
    legs = n; 
  } 

